import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"人物代言","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"prompts/spokesperson.md","filePath":"prompts/spokesperson.md","lastUpdated":1787714366000}'),l={name:"prompts/spokesperson.md"};function s(d,t,i,n,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="人物代言" tabindex="-1">人物代言 <a class="header-anchor" href="#人物代言" aria-label="Permalink to &quot;人物代言&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">待补充</p><p>这一页还没有实战 Prompt。下面是已确定的问题框架和必须遵守的边界。</p></div><h2 id="边界-先说不能做的" tabindex="-1">边界：先说不能做的 <a class="header-anchor" href="#边界-先说不能做的" aria-label="Permalink to &quot;边界：先说不能做的&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">这条线不能碰</p><p><strong>不要生成真实人物的形象或声音用于商业广告，除非你持有该人物明确的书面授权。</strong></p><p>包括但不限于：明星、公众人物、你的客户、你认识的任何人。这不是技术问题，是肖像权、声音权和人格权问题，在中国《民法典》和多数国家/地区的法律下都会构成侵权，平台也普遍禁止。</p><p>「看起来像某人但不是某人」同样有风险——如果普通观众会误认，就可能被认定为侵权。</p></div><p>安全的做法是：<strong>生成完全虚构的人物形象</strong>，或使用有明确授权的真人素材。</p><h2 id="这一页要解决的问题" tabindex="-1">这一页要解决的问题 <a class="header-anchor" href="#这一页要解决的问题" aria-label="Permalink to &quot;这一页要解决的问题&quot;">​</a></h2><p>在合规前提下，虚构代言人的三个技术难点：</p><ol><li><strong>人物一致性</strong> —— 同一个虚构人物在多个镜头、多次生成之间保持同一张脸。</li><li><strong>表演自然度</strong> —— 当前 AI 视频里的人物表情容易僵硬、动作幅度不自然，这是最容易露馅的地方。</li><li><strong>口型同步</strong> —— 有口播时，口型和语音对不上非常明显。</li></ol><h2 id="已知的方向" tabindex="-1">已知的方向 <a class="header-anchor" href="#已知的方向" aria-label="Permalink to &quot;已知的方向&quot;">​</a></h2><p><strong>一致性</strong>：主流工具支持传入人物参考图。先用图像模型生成并锁定一张满意的人物定妆照，之后所有镜头都以它为参考。见 <a href="/method/brand-consistency">品牌一致性控制</a>。</p><p><strong>表演</strong>：绕过去比硬碰更划算。少用大幅动作和复杂表情，多用侧脸、背影、局部特写、手部动作、被遮挡的构图。<strong>观众看不见的地方，AI 就不会画错。</strong></p><p><strong>口型</strong>：如果同步质量不达标，改用画外音——人物出画面但不说话，旁白单独配。这是目前最稳的解法。</p><h2 id="待填内容" tabindex="-1">待填内容 <a class="header-anchor" href="#待填内容" aria-label="Permalink to &quot;待填内容&quot;">​</a></h2><h3 id="人物定妆流程" tabindex="-1">人物定妆流程 <a class="header-anchor" href="#人物定妆流程" aria-label="Permalink to &quot;人物定妆流程&quot;">​</a></h3><ul><li>怎么生成初始人物形象：</li><li>用什么参数锁定：</li><li>一致性实际能保持到什么程度：</li></ul><h3 id="可用的镜头类型" tabindex="-1">可用的镜头类型 <a class="header-anchor" href="#可用的镜头类型" aria-label="Permalink to &quot;可用的镜头类型&quot;">​</a></h3><p>哪些构图能出片，哪些必然翻车：</p><table tabindex="0"><thead><tr><th>镜头类型</th><th>效果</th><th>备注</th></tr></thead><tbody><tr><td>正面近景说话</td><td></td><td></td></tr><tr><td>侧脸中景</td><td></td><td></td></tr><tr><td>背影</td><td></td><td></td></tr><tr><td>手部特写</td><td></td><td></td></tr></tbody></table><h3 id="表演的替代方案" tabindex="-1">表演的替代方案 <a class="header-anchor" href="#表演的替代方案" aria-label="Permalink to &quot;表演的替代方案&quot;">​</a></h3><ul><li>用什么代替正面表演：</li><li>效果对比：</li></ul><h3 id="翻车记录" tabindex="-1">翻车记录 <a class="header-anchor" href="#翻车记录" aria-label="Permalink to &quot;翻车记录&quot;">​</a></h3><ul><li>出过什么问题：</li><li>怎么补救的：</li></ul><hr><p>写作格式参考 <a href="/templates/prompt-card">Prompt 卡片模板</a>。</p>',24)])])}const m=a(l,[["render",s]]);export{u as __pageData,m as default};
